// The Winterfest Arcade: ten small games that pay Snowbells and Workshop materials. Keyboard, mouse and touch all work.
import { esc, today } from "../util.js";
import { addMats, MATS, arcadeState } from "./more.js";
import { forecast } from "./data.js";
import { settings } from "../store.js";

const AW = 720, AH = 420, clamp = (v, a, b) => Math.max(a, Math.min(b, v)), rnd = (a, b) => a + Math.random() * (b - a), pick = (l) => l[Math.floor(Math.random() * l.length)];
const sky = (g, a = "#132454", b = "#46619a") => { const q = g.createLinearGradient(0, 0, 0, AH); q.addColorStop(0, a); q.addColorStop(1, b); g.fillStyle = q; g.fillRect(0, 0, AW, AH); };
const flakes = (g, t) => { g.fillStyle = "rgba(255,255,255,.7)"; for (let i = 0; i < 34; i++) g.fillRect((i * 97 + Math.sin(t + i) * 12) % AW, (i * 53 + t * (24 + i % 5 * 6)) % AH, 3, 3); };
const gift = (g, x, y, s = 14, c = "#e0343e", r = "#ffd27a") => { g.fillStyle = c; g.fillRect(x - s, y - s, s * 2, s * 2); g.fillStyle = r; g.fillRect(x - s * .2, y - s, s * .4, s * 2); g.fillRect(x - s, y - s * .2, s * 2, s * .4); };
const star = (g, x, y, r = 12, c = "#ffd84d") => { g.fillStyle = c; g.beginPath(); for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + i * Math.PI / 5, q = i % 2 ? r * .45 : r; g.lineTo(x + Math.cos(a) * q, y + Math.sin(a) * q); } g.closePath(); g.fill(); };
const pine = (g, x, y, s = 1) => { g.fillStyle = "#5a3a22"; g.fillRect(x - 4 * s, y + 12 * s, 8 * s, 10 * s); for (const [h, w] of [[12, 22], [-4, 17], [-18, 12]]) { g.fillStyle = "#256b44"; g.beginPath(); g.moveTo(x - w * s, y + h * s); g.lineTo(x + w * s, y + h * s); g.lineTo(x, y + (h - 20) * s); g.fill(); } };
const text = (g, t, x, y, c = "#fff", f = "800 16px system-ui", al = "center") => { g.font = f; g.textAlign = al; g.fillStyle = c; g.fillText(t, x, y); };
const COLORS = ["#e0343e", "#3fae6a", "#3f8fe0", "#f2c23c"], ARROWS = ["ArrowLeft", "ArrowUp", "ArrowDown", "ArrowRight"], ARROW_T = ["←", "↑", "↓", "→"];

const sled = (a) => { let x = 360, hits = 0, T = 0, next = 0, obs = []; return { move: (p) => (x = clamp(p, 40, AW - 40)), tick(dt) { T += dt; const v = 240 + T * 9; if (a.keys.has("ArrowLeft") || a.keys.has("a")) x -= 400 * dt; if (a.keys.has("ArrowRight") || a.keys.has("d")) x += 400 * dt; x = clamp(x, 40, AW - 40); if ((next -= dt) <= 0) { next = Math.max(.2, .58 - T * .012); const r = Math.random(); obs.push({ x: rnd(30, AW - 30), y: AH + 30, k: r < .3 ? "gift" : r < .38 ? "star" : "tree" }); } for (const o of obs) { o.y -= v * dt; if (!o.hit && Math.abs(o.y - 104) < 25 && Math.abs(o.x - x) < 31) { o.hit = 1; if (o.k === "tree") { hits++; a.add(-3); a.blip(); if (hits >= 3) a.end(); } else { a.add(o.k === "star" ? 6 : 2); a.tone(o.k === "star" ? 880 : 660); } } } obs = obs.filter((o) => !o.hit && o.y > -40); }, draw(g, t) { g.fillStyle = "#e9f2f9"; g.fillRect(0, 0, AW, AH); g.strokeStyle = "#cfe0ec"; g.lineWidth = 3; for (let i = 0; i < 9; i++) { const y = (i * 60 - t * 240) % 480 + 480; g.beginPath(); g.moveTo(90 + i * 70, y); g.lineTo(100 + i * 70, y + 26); g.stroke(); } for (const o of obs) o.k === "tree" ? pine(g, o.x, o.y - 8, 1.1) : o.k === "gift" ? gift(g, o.x, o.y) : star(g, o.x, o.y, 15); g.fillStyle = "#b5432a"; g.fillRect(x - 20, 86, 40, 30); g.strokeStyle = "#ffd27a"; g.lineWidth = 4; g.beginPath(); g.moveTo(x - 24, 120); g.lineTo(x + 24, 120); g.stroke(); g.fillStyle = "#e8862e"; g.beginPath(); g.arc(x, 82, 13, 0, 7); g.fill(); text(g, "♥".repeat(3 - hits), AW / 2, 28, "#e0345e", "900 20px system-ui"); } }; };

const snowball = (a) => { const holes = []; for (let r = 0; r < 2; r++) for (let c = 0; c < 4; c++) holes.push({ x: 120 + c * 160, y: 170 + r * 150, k: "", until: 0 }); let T = 0, next = 0, balls = [], pops = []; const throwAt = (x, y) => { balls.push({ x, y, t: 0 }); a.blip(); }; let cur = 0; return { down: throwAt, key: (k) => { if (k === "ArrowLeft") cur = (cur + 7) % 8; if (k === "ArrowRight") cur = (cur + 1) % 8; if (k === "ArrowUp" || k === "ArrowDown") cur = (cur + 4) % 8; if (k === " ") throwAt(holes[cur].x, holes[cur].y - 20); }, tick(dt) { T += dt; if ((next -= dt) <= 0) { next = Math.max(.3, .75 - T * .014); const free = holes.filter((h) => !h.k); if (free.length) { const h = pick(free), r = Math.random(); h.k = r < .62 ? "snowman" : r < .82 ? "friend" : "gold"; h.until = T + Math.max(.8, 1.7 - T * .025); } } for (const h of holes) if (h.k && T > h.until) h.k = ""; for (const b of balls) { b.t += dt; if (b.t >= .16 && !b.done) { b.done = 1; const h = holes.find((q) => q.k && Math.abs(q.x - b.x) < 52 && Math.abs(q.y - 15 - b.y) < 62); if (h) { const n = h.k === "gold" ? 4 : h.k === "friend" ? -3 : 1; a.add(n); pops.push({ x: h.x, y: h.y - 70, t: n, life: .8 }); a.tone(n > 0 ? 720 : 180); h.k = ""; } } } balls = balls.filter((b) => b.t < .32); for (const p of pops) p.life -= dt; pops = pops.filter((p) => p.life > 0); }, draw(g, t) { sky(g, "#1c356e", "#7fa4cf"); g.fillStyle = "#eef4fa"; g.fillRect(0, 150, AW, 270); holes.forEach((h, i) => { if (h.k === "snowman" || h.k === "gold") { g.fillStyle = h.k === "gold" ? "#ffd84d" : "#fff"; g.beginPath(); g.arc(h.x, h.y - 2, 25, 0, 7); g.arc(h.x, h.y - 38, 17, 0, 7); g.fill(); g.fillStyle = "#23233a"; g.fillRect(h.x - 13, h.y - 66, 26, 12); g.fillRect(h.x - 19, h.y - 55, 38, 3); g.fillRect(h.x - 7, h.y - 42, 3, 3); g.fillRect(h.x + 4, h.y - 42, 3, 3); g.fillStyle = "#f2892e"; g.fillRect(h.x, h.y - 36, 11, 3); } else if (h.k === "friend") { g.fillStyle = "#3fae6a"; g.fillRect(h.x - 15, h.y - 24, 30, 42); g.fillStyle = "#f3cdb2"; g.beginPath(); g.arc(h.x, h.y - 38, 15, 0, 7); g.fill(); g.fillStyle = "#e0343e"; g.beginPath(); g.moveTo(h.x - 16, h.y - 44); g.lineTo(h.x, h.y - 76); g.lineTo(h.x + 16, h.y - 44); g.fill(); text(g, "Don't!", h.x, h.y + 36, "#b3202c", "800 12px system-ui"); } g.fillStyle = "#c9dbe9"; g.beginPath(); g.ellipse(h.x, h.y + 22, 56, 18, 0, 0, 7); g.fill(); if (i === cur) { g.strokeStyle = "#ffd27a"; g.lineWidth = 3; g.beginPath(); g.ellipse(h.x, h.y + 22, 60, 22, 0, 0, 7); g.stroke(); } }); for (const b of balls) { const k = Math.min(1, b.t / .16), x = AW / 2 + (b.x - AW / 2) * k, y = AH + (b.y - AH) * k - Math.sin(k * 3.14) * 50; g.fillStyle = "#fff"; g.strokeStyle = "#8fb0cc"; g.beginPath(); g.arc(x, y, 14 - k * 6, 0, 7); g.fill(); g.stroke(); } for (const p of pops) text(g, (p.t > 0 ? "+" : "") + p.t, p.x, p.y - (1 - p.life) * 30, p.t > 0 ? "#ffb52e" : "#e0343e", "900 24px system-ui"); } }; };

const carol = (a) => { const melody = [2, 2, 2, 2, 2, 2, 2, 3, 0, 1, 2, 2, 2, 2, 2, 2, 2, 1, 1, 2, 1, 3, 2, 2, 2, 2, 2, 2, 2, 3, 0, 1, 2, 3, 3, 3, 3, 3, 2, 2, 2, 3, 3, 2, 1, 0], beats = [1, 1, 2, 1, 1, 2, 1, 1, 1.5, .5, 4, 1, 1, 2, 1, 1, 2, 1, 1, 1, 1, 4, 1, 1, 2, 1, 1, 2, 1, 1, 1.5, .5, 4, 1, 1, 1.5, .5, 1, 1, 1, .5, .5, 1, 1, 1, 4], FR = [392, 440, 494, 587], KEY = ["a", "s", "d", "f"], beat = .36; let at = 1.2; const notes = melody.map((l, i) => { const n = { l, at }; at += beats[i] * beat; return n; }); let T = 0, combo = 0, maxC = 0, msg = "", msgT = 0; const end = at + 1; const press = (l) => { const n = notes.filter((x) => !x.done && x.l === l).sort((p, q) => p.at - q.at)[0]; const d = n ? Math.abs(n.at - T) : 9; if (d < .17) { n.done = 1; const good = d < .07; combo++; maxC = Math.max(maxC, combo); a.add((good ? 3 : 1) + Math.floor(combo / 10)); a.tone(FR[l], .22); msg = good ? "PERFECT" : "Good"; } else { combo = 0; msg = "Miss"; a.blip(); } msgT = T + .4; }; return { key: (k) => { const i = KEY.indexOf(k); if (i >= 0) press(i); else if (ARROWS.includes(k)) press(ARROWS.indexOf(k)); }, down: (x) => press(clamp(Math.floor((x - 180) / 90), 0, 3)), tick(dt) { T += dt; for (const n of notes) if (!n.done && T - n.at > .18) { n.done = 1; combo = 0; msg = "Miss"; msgT = T + .3; } if (T > end) a.end(); }, draw(g) { sky(g, "#12122e", "#3a2452"); for (let i = 0; i < 4; i++) { g.fillStyle = i % 2 ? "rgba(255,255,255,.06)" : "rgba(255,255,255,.1)"; g.fillRect(180 + i * 90, 0, 90, AH); g.fillStyle = COLORS[i]; g.beginPath(); g.arc(225 + i * 90, 360, 27, 0, 7); g.fill(); text(g, KEY[i].toUpperCase(), 225 + i * 90, 367, "#fff", "900 20px system-ui"); } for (const n of notes) { if (n.done) continue; const y = 360 - (n.at - T) * 300; if (y < -30 || y > AH + 30) continue; g.fillStyle = COLORS[n.l]; g.strokeStyle = "#fff"; g.lineWidth = 3; g.beginPath(); g.arc(225 + n.l * 90, y, 21, 0, 7); g.fill(); g.stroke(); } text(g, `Combo ${combo}`, 90, 200, "#ffd27a", "900 22px system-ui"); text(g, `Best ${maxC}`, 90, 226, "#c9c3e0", "700 14px system-ui"); if (T < msgT) text(g, msg, 610, 210, msg === "Miss" ? "#ff6a7a" : "#7dff8a", "900 24px system-ui"); } }; };

const chimney = (a) => { let T = 0, houses = [], next = 0, drops = [], cool = 0, pops = []; const drop = () => { if (cool > 0) return; cool = .22; drops.push({ x: 150, y: 74, vy: 40 }); a.blip(); }; return { key: (k) => { if (k === " " || k === "ArrowDown") drop(); }, down: drop, tick(dt) { T += dt; cool -= dt; const v = 170 + T * 5; if ((next -= dt) <= 0) { next = rnd(.8, 1.5) - Math.min(.35, T * .01); houses.push({ x: AW + 70, w: rnd(90, 140), h: rnd(90, 170), c: pick(["#b5432a", "#3f6f94", "#7d5fa8", "#3f8a58"]), done: 0 }); } for (const h of houses) h.x -= v * dt; houses = houses.filter((h) => h.x > -120); for (const d of drops) { d.x -= v * .1 * dt; d.vy += 620 * dt; d.y += d.vy * dt; for (const h of houses) { const roof = AH - 40 - h.h - 34, cx = h.x + h.w * .68; if (!d.gone && d.y > roof - 8 && d.y < roof + 26 && Math.abs(d.x - cx) < 22 && !h.done) { d.gone = 1; h.done = 1; const perfect = Math.abs(d.x - cx) < 8; a.add(perfect ? 5 : 3); a.tone(perfect ? 880 : 660); pops.push({ x: cx, y: roof - 16, t: perfect ? "+5" : "+3", life: .8 }); } } if (d.y > AH - 40) d.gone = 1; } drops = drops.filter((d) => !d.gone); for (const p of pops) p.life -= dt; pops = pops.filter((p) => p.life > 0); }, draw(g, t) { sky(g, "#0d1838", "#34508a"); g.fillStyle = "#fff6c2"; g.beginPath(); g.arc(600, 70, 34, 0, 7); g.fill(); flakes(g, t); g.fillStyle = "#eef4fa"; g.fillRect(0, AH - 40, AW, 40); for (const h of houses) { const y = AH - 40 - h.h; g.fillStyle = "#6a4528"; g.fillRect(h.x + h.w * .68 - 13, y - 56, 26, 40); g.fillStyle = h.done ? "#ffd27a" : "#222"; g.fillRect(h.x + h.w * .68 - 16, y - 60, 32, 7); g.fillStyle = h.c; g.fillRect(h.x, y, h.w, h.h); g.fillStyle = "#eef4fa"; g.beginPath(); g.moveTo(h.x - 10, y + 2); g.lineTo(h.x + h.w / 2, y - 34); g.lineTo(h.x + h.w + 10, y + 2); g.fill(); g.fillStyle = "#ffd982"; g.fillRect(h.x + 16, y + 22, 22, 22); } for (const d of drops) gift(g, d.x, d.y, 10); g.fillStyle = "#b5432a"; g.fillRect(118, 48, 66, 24); g.strokeStyle = "#ffd27a"; g.lineWidth = 4; g.beginPath(); g.moveTo(110, 78); g.lineTo(190, 78); g.quadraticCurveTo(202, 76, 198, 62); g.stroke(); gift(g, 136, 40, 9, "#3fae6a"); gift(g, 160, 40, 9); for (const p of pops) text(g, p.t, p.x, p.y - (1 - p.life) * 26, "#ffd27a", "900 20px system-ui"); } }; };

const skate = (a) => { let x = 360, y = 220, vx = 0, vy = 0, stars = [], cracks = [], T = 0, fall = 0, next = 0, tx = null, ty = null; const addStar = () => stars.push({ x: rnd(50, AW - 50), y: rnd(70, AH - 40) }); addStar(); addStar(); addStar(); return { move: (p, q) => { tx = p; ty = q; }, tick(dt) { T += dt; let ax = 0, ay = 0; const K = a.keys; if (K.has("ArrowLeft") || K.has("a")) ax--; if (K.has("ArrowRight") || K.has("d")) ax++; if (K.has("ArrowUp") || K.has("w")) ay--; if (K.has("ArrowDown") || K.has("s")) ay++; if (!ax && !ay && tx != null) { const d = Math.hypot(tx - x, ty - y); if (d > 16) { ax = (tx - x) / d; ay = (ty - y) / d; } } vx += ax * 760 * dt; vy += ay * 760 * dt; const f = Math.max(0, 1 - dt * .9); vx *= f; vy *= f; x += vx * dt; y += vy * dt; if (x < 22 || x > AW - 22) { vx *= -.7; x = clamp(x, 22, AW - 22); } if (y < 52 || y > AH - 22) { vy *= -.7; y = clamp(y, 52, AH - 22); } for (const s of stars) if (Math.hypot(s.x - x, s.y - y) < 30) { s.got = 1; a.add(2); a.tone(760); } if (stars.some((s) => s.got)) { stars = stars.filter((s) => !s.got); addStar(); } if ((next -= dt) <= 0) { next = Math.max(.9, 2.3 - T * .05); let cx, cy, g = 0; do { cx = rnd(50, AW - 50); cy = rnd(70, AH - 40); } while (Math.hypot(cx - x, cy - y) < 130 && g++ < 20); cracks.push({ x: cx, y: cy, r: rnd(26, 42), at: T + .85, end: T + 7 }); } for (const c of cracks) if (T > c.at && Math.hypot(c.x - x, c.y - y) < c.r + 6 && T > fall) { fall = T + 1.3; a.add(-3); a.blip(); vx = -vx * .5; vy = -vy * .5; } cracks = cracks.filter((c) => T < c.end); }, draw(g) { g.fillStyle = "#bfe6f7"; g.fillRect(0, 0, AW, AH); g.strokeStyle = "rgba(255,255,255,.75)"; g.lineWidth = 2; for (let i = 0; i < 12; i++) { g.beginPath(); g.arc(70 + i * 62, 90 + (i * 83) % 280, 34, i, i + 2); g.stroke(); } for (const c of cracks) { const on = T > c.at; g.fillStyle = on ? "#16395c" : "rgba(22,57,92,.2)"; g.beginPath(); g.arc(c.x, c.y, c.r, 0, 7); g.fill(); g.strokeStyle = "#e8f6ff"; g.lineWidth = 2; for (let i = 0; i < 5; i++) { const q = i * 1.26; g.beginPath(); g.moveTo(c.x, c.y); g.lineTo(c.x + Math.cos(q) * c.r * 1.25, c.y + Math.sin(q) * c.r * 1.25); g.stroke(); } } for (const s of stars) star(g, s.x, s.y, 15); if (!(T < fall && Math.floor(T * 10) % 2)) { g.fillStyle = "#e8862e"; g.beginPath(); g.arc(x, y, 17, 0, 7); g.fill(); g.fillStyle = "#fff6e6"; g.beginPath(); g.arc(x, y + 4, 9, 0, 7); g.fill(); g.fillStyle = "#e0343e"; g.fillRect(x - 15, y - 15, 30, 5); } } }; };

const stack = (a) => { let blocks = [{ x: 210, w: 300 }], cur = { x: 0, w: 300, d: 1 }, cam = 0, speed = 240, chips = [], ended = false; const H = 26; const drop = () => { if (ended) return; const top = blocks.at(-1), l = Math.max(cur.x, top.x), r = Math.min(cur.x + cur.w, top.x + top.w), w = r - l; if (w <= 2) { ended = true; a.blip(); return a.end(); } const perfect = Math.abs(cur.x - top.x) < 6; const nx = perfect ? top.x : l, nw = perfect ? top.w : w; if (!perfect) chips.push({ x: cur.x < top.x ? cur.x : r, w: cur.w - w, y: blocks.length, vy: 0, o: 0 }); blocks.push({ x: nx, w: nw }); a.add(perfect ? 4 : 1); a.tone(perfect ? 880 : 520 + blocks.length * 8); speed = Math.min(620, speed + 14); cur = { x: blocks.length % 2 ? 0 : AW - nw, w: nw, d: blocks.length % 2 ? 1 : -1 }; }; return { key: (k) => k === " " && drop(), down: drop, tick(dt) { cur.x += cur.d * speed * dt; if (cur.x < 0 || cur.x + cur.w > AW) { cur.d *= -1; cur.x = clamp(cur.x, 0, AW - cur.w); } cam += (Math.max(0, blocks.length - 8) * H - cam) * Math.min(1, dt * 6); for (const c of chips) { c.vy += 600 * dt; c.o += c.vy * dt; } chips = chips.filter((c) => c.o < 500); }, draw(g, t) { sky(g, "#172a60", "#7fa4cf"); flakes(g, t); const Y = (i) => AH - 34 - i * H + cam; g.fillStyle = "#eef4fa"; g.fillRect(0, Y(-1) - 4, AW, 200); blocks.forEach((b, i) => { g.fillStyle = i % 2 ? "#2f8a58" : "#256b44"; g.fillRect(b.x, Y(i), b.w, H - 1); g.fillStyle = COLORS[i % 4]; for (let q = b.x + 12; q < b.x + b.w - 6; q += 34) { g.beginPath(); g.arc(q, Y(i) + 13, 4, 0, 7); g.fill(); } }); g.fillStyle = "#3fae6a"; g.fillRect(cur.x, Y(blocks.length), cur.w, H - 1); g.fillStyle = "rgba(47,138,88,.7)"; for (const c of chips) g.fillRect(c.x, Y(c.y) + c.o, c.w, H - 1); star(g, cur.x + cur.w / 2, Y(blocks.length) - 16, 12); } }; };

const wrap = (a) => { let items = [], T = 0, next = .2, miss = 0, cur = 0; const press = (i) => { const o = items.filter((x) => !x.done).sort((p, q) => q.x - p.x)[0]; if (!o) return; if (o.c === i) { o.done = 1; o.ok = 1; a.add(o.x > 460 ? 3 : 1); a.tone(520 + i * 90); } else { o.done = 1; miss++; a.add(-1); a.blip(); if (miss >= 5) a.end(); } }; return { key: (k) => { const i = ARROWS.indexOf(k); if (i >= 0) press(i); }, down: (x, y) => { if (y > 300) press(clamp(Math.floor(x / (AW / 4)), 0, 3)); }, tick(dt) { T += dt; const v = 130 + T * 6; if ((next -= dt) <= 0) { next = Math.max(.42, 1.05 - T * .02); items.push({ x: -40, c: Math.floor(Math.random() * 4) }); } for (const o of items) { o.x += (o.done ? v * 1.8 : v) * dt; if (!o.done && o.x > AW - 40) { o.done = 1; miss++; a.blip(); if (miss >= 5) a.end(); } } items = items.filter((o) => o.x < AW + 50); }, draw(g) { g.fillStyle = "#3a2a22"; g.fillRect(0, 0, AW, AH); g.fillStyle = "#5a4034"; for (let i = 0; i < 9; i++) g.fillRect(i * 88, 0, 3, 200); g.fillStyle = "#23232c"; g.fillRect(0, 170, AW, 72); g.fillStyle = "#3a3a44"; for (let x = (T * 130) % 40; x < AW; x += 40) g.fillRect(x, 170, 3, 72); for (const o of items) { if (o.done && !o.ok) { gift(g, o.x, 196, 22, "#555", "#777"); continue; } gift(g, o.x, 196, 22, o.done ? COLORS[o.c] : "#c9b18a", o.done ? "#fff" : "#a58f6a"); if (!o.done) { g.fillStyle = COLORS[o.c]; g.beginPath(); g.arc(o.x, 150, 14, 0, 7); g.fill(); text(g, ARROW_T[o.c], o.x, 156, "#fff", "900 16px system-ui"); } } COLORS.forEach((c, i) => { const x = (i + .5) * AW / 4; g.fillStyle = c; g.beginPath(); g.roundRect(x - 62, 310, 124, 80, 12); g.fill(); text(g, ARROW_T[i], x, 362, "#fff", "900 34px system-ui"); }); text(g, `Misses ${miss}/5`, AW / 2, 30, "#ffd27a"); } }; };

const memory = (a) => { const icons = ["gift", "star", "tree", "bell", "snow", "cane", "sock", "ball"]; let cards = [], open = [], lock = 0, T = 0, cur = 0, round = 1; const deal = () => { cards = [...icons, ...icons].sort(() => Math.random() - .5).map((k) => ({ k, up: false, done: false })); open = []; }; deal(); const flip = (i) => { const c = cards[i]; if (!c || c.up || c.done || lock > T) return; c.up = true; open.push(c); a.tone(600); if (open.length === 2) { if (open[0].k === open[1].k) { open[0].done = open[1].done = true; open = []; a.add(4); a.tone(880); if (cards.every((x) => x.done)) { a.add(8 + round * 2); round++; lock = T + .5; setTimeout(deal, 420); } } else { lock = T + .65; const [p, q] = open; setTimeout(() => { p.up = q.up = false; }, 620); open = []; a.add(-1); } } }; const rect = (i) => [152 + (i % 4) * 106, 40 + Math.floor(i / 4) * 94, 94, 84]; const ico = (g, k, x, y) => { if (k === "gift") gift(g, x, y, 18); else if (k === "star") star(g, x, y, 22); else if (k === "tree") pine(g, x, y - 2, .9); else if (k === "bell") { g.fillStyle = "#f2c23c"; g.beginPath(); g.moveTo(x - 18, y + 14); g.quadraticCurveTo(x - 12, y - 20, x, y - 20); g.quadraticCurveTo(x + 12, y - 20, x + 18, y + 14); g.fill(); g.beginPath(); g.arc(x, y + 17, 5, 0, 7); g.fill(); } else if (k === "snow") { g.strokeStyle = "#6cc8ff"; g.lineWidth = 4; for (let i = 0; i < 3; i++) { const q = i * 1.05; g.beginPath(); g.moveTo(x - Math.cos(q) * 21, y - Math.sin(q) * 21); g.lineTo(x + Math.cos(q) * 21, y + Math.sin(q) * 21); g.stroke(); } } else if (k === "cane") { g.strokeStyle = "#e0343e"; g.lineWidth = 8; g.lineCap = "round"; g.beginPath(); g.moveTo(x + 8, y + 22); g.lineTo(x + 8, y - 8); g.arc(x - 2, y - 8, 10, 0, Math.PI, true); g.stroke(); g.lineCap = "butt"; } else if (k === "sock") { g.fillStyle = "#d3312f"; g.fillRect(x - 8, y - 22, 16, 30); g.beginPath(); g.ellipse(x + 2, y + 12, 18, 10, 0, 0, 7); g.fill(); g.fillStyle = "#fff"; g.fillRect(x - 10, y - 24, 20, 8); } else { g.fillStyle = "#9a5be0"; g.beginPath(); g.arc(x, y + 2, 20, 0, 7); g.fill(); g.fillStyle = "#ffd27a"; g.fillRect(x - 5, y - 24, 10, 7); } }; return { down: (x, y) => { const i = cards.findIndex((_, n) => { const [p, q, w, h] = rect(n); return x > p && x < p + w && y > q && y < q + h; }); if (i >= 0) { cur = i; flip(i); } }, key: (k) => { if (k === "ArrowLeft") cur = (cur + 15) % 16; if (k === "ArrowRight") cur = (cur + 1) % 16; if (k === "ArrowUp") cur = (cur + 12) % 16; if (k === "ArrowDown") cur = (cur + 4) % 16; if (k === " ") flip(cur); }, tick(dt) { T += dt; }, draw(g) { sky(g, "#14304a", "#2f6b58"); cards.forEach((c, i) => { const [x, y, w, h] = rect(i); g.fillStyle = c.done ? "rgba(255,255,255,.25)" : c.up ? "#fff8ea" : "#b5303a"; g.beginPath(); g.roundRect(x, y, w, h, 9); g.fill(); if (i === cur) { g.strokeStyle = "#ffd27a"; g.lineWidth = 3; g.stroke(); } if (c.up || c.done) ico(g, c.k, x + w / 2, y + h / 2); else star(g, x + w / 2, y + h / 2, 13, "#ffd27a"); }); } }; };

const cookie = (a) => { const PAL = ["#f6e7c8", "#e0343e", "#3fae6a", "#6cc8ff"]; let want = [], mine = [], cur = 5, round = 1; const deal = () => { const n = Math.min(10, 3 + round); want = Array(16).fill(0); mine = Array(16).fill(0); for (let i = 0; i < n; i++) want[Math.floor(Math.random() * 16)] = 1 + Math.floor(Math.random() * 3); }; deal(); const hit = (i) => { mine[i] = (mine[i] + 1) % 4; a.tone(420 + mine[i] * 120, .06); if (mine.every((v, q) => v === want[q])) { a.add(4 + round * 2); a.tone(880); round++; deal(); } }; const cell = (ox, i) => [ox + (i % 4) * 56, 104 + Math.floor(i / 4) * 56]; const face = (g, ox, arr, live) => { g.fillStyle = "#c98f4e"; g.beginPath(); g.arc(ox + 112, 216, 164, 0, 7); g.fill(); arr.forEach((v, i) => { const [x, y] = cell(ox, i); g.fillStyle = PAL[v]; g.beginPath(); g.roundRect(x + 3, y + 3, 50, 50, 9); g.fill(); if (live && i === cur) { g.strokeStyle = "#111"; g.lineWidth = 3; g.stroke(); } }); }; return { down: (x, y) => { for (let i = 0; i < 16; i++) { const [p, q] = cell(420, i); if (x > p && x < p + 56 && y > q && y < q + 56) { cur = i; hit(i); } } }, key: (k) => { if (k === "ArrowLeft") cur = (cur + 15) % 16; if (k === "ArrowRight") cur = (cur + 1) % 16; if (k === "ArrowUp") cur = (cur + 12) % 16; if (k === "ArrowDown") cur = (cur + 4) % 16; if (k === " ") hit(cur); }, tick() {}, draw(g) { g.fillStyle = "#6a3f2a"; g.fillRect(0, 0, AW, AH); face(g, 76, want, false); face(g, 420, mine, true); text(g, "Copy this cookie", 188, 40, "#ffe9c8"); text(g, "Your cookie (tap to change icing)", 532, 40, "#ffe9c8"); text(g, `Cookie ${round}`, AW / 2, 406, "#ffd27a"); } }; };

const WORDS = ["SNOWFLAKE", "MITTENS", "REINDEER", "CHIMNEY", "STOCKING", "LANTERN", "EVERGREEN", "SLEIGH", "COCOA", "ORNAMENT", "GINGERBREAD", "FIREPLACE", "PRESENT", "SNOWMAN", "ICICLE", "MISTLETOE", "CAROL", "WREATH", "BLIZZARD", "TINSEL", "NUTCRACKER", "PEPPERMINT", "SCARF", "HOLLY", "FROSTBITE", "WINTERFEST", "SNOWBELL", "CANDLE", "TOBOGGAN", "EGGNOG"];
const shuffle = (w) => { let s = w; for (let i = 0; i < 8 && s === w; i++) s = [...w].sort(() => Math.random() - .5).join(""); return s; };
const scramble = (a) => { let word = pick(WORDS), mix = shuffle(word), shown = 0; const next = () => { let n = word; while (n === word) n = pick(WORDS); word = n; mix = shuffle(word); shown = 0; if (a.input) { a.input.value = ""; a.input.focus({ preventScroll: true }); } }; a.onInput = (v) => { if (v.trim().toUpperCase() === word) { a.add(Math.max(1, word.length - shown * 2)); a.tone(880); next(); } }; a.hint = () => { if (shown < word.length - 2) { shown++; a.blip(); } }; a.skip = () => { a.add(-1); next(); }; return { tick() {}, draw(g, t) { sky(g, "#1c2b5e", "#5a3f7a"); flakes(g, t); const n = mix.length, w = Math.min(58, 640 / n); [...mix].forEach((c, i) => { const x = AW / 2 + (i - (n - 1) / 2) * w, y = 150 + Math.sin(t * 2 + i) * 4; g.fillStyle = "#fff8ea"; g.beginPath(); g.roundRect(x - w * .44, y - 34, w * .88, 62, 8); g.fill(); text(g, c, x, y + 8, "#b5303a", `900 ${Math.floor(w * .62)}px system-ui`); }); if (shown) text(g, `Starts with: ${word.slice(0, shown)}`, AW / 2, 232, "#ffd27a", "800 20px system-ui"); } }; };

const reindeer = (a) => { let y = 210, vy = 0, T = 0, next = 0, rings = [], clouds = [], hits = 0, aim = null; return { move: (_x, p) => (aim = p), tick(dt) { T += dt; let ay = 0; if (a.keys.has("ArrowUp") || a.keys.has("w")) ay--; if (a.keys.has("ArrowDown") || a.keys.has("s")) ay++; if (!ay && aim != null && Math.abs(aim - y) > 10) ay = Math.sign(aim - y); vy += ay * 900 * dt; vy *= Math.max(0, 1 - dt * 4); y = clamp(y + vy * dt, 36, AH - 36); const v = 230 + T * 7; if ((next -= dt) <= 0) { next = Math.max(.42, 1.0 - T * .014); if (Math.random() < .62) rings.push({ x: AW + 40, y: rnd(56, AH - 56), r: 34 }); else clouds.push({ x: AW + 40, y: rnd(48, AH - 48), r: 24 }); } for (const q of rings) { q.x -= v * dt; if (!q.got && Math.abs(q.x - 110) < 28 && Math.abs(q.y - y) < q.r + 12) { q.got = 1; a.add(3); a.tone(780); } } for (const c of clouds) { c.x -= v * dt; if (!c.hit && Math.hypot(c.x - 110, c.y - y) < c.r + 16) { c.hit = 1; hits++; a.add(-2); a.blip(); if (hits >= 3) a.end(); } } rings = rings.filter((q) => !q.got && q.x > -40); clouds = clouds.filter((c) => !c.hit && c.x > -40); }, draw(g, t) { sky(g, "#0b1a40", "#2f4e88"); flakes(g, t); for (const q of rings) { g.strokeStyle = "#ffd84d"; g.lineWidth = 5; g.beginPath(); g.ellipse(q.x, q.y, 12, q.r, 0, 0, 7); g.stroke(); } for (const c of clouds) { g.fillStyle = "#485878"; g.beginPath(); g.arc(c.x, c.y, c.r, 0, 7); g.arc(c.x - 16, c.y + 6, 16, 0, 7); g.arc(c.x + 16, c.y + 6, 16, 0, 7); g.fill(); } g.fillStyle = "#b5432a"; g.fillRect(84, y - 10, 44, 22); g.fillStyle = "#ffd27a"; g.fillRect(80, y + 12, 52, 4); g.fillStyle = "#8a5a32"; g.beginPath(); g.arc(138, y - 4, 10, 0, 7); g.fill(); g.fillStyle = "#e0343e"; g.beginPath(); g.arc(148, y - 4, 4, 0, 7); g.fill(); text(g, "♥".repeat(3 - hits), AW / 2, 28, "#ff6a7a", "900 20px system-ui"); } }; };

const icicles = (a) => { let x = 360, T = 0, next = 0, items = [], hits = 0, aim = null; return { move: (p) => (aim = p), tick(dt) { T += dt; if (a.keys.has("ArrowLeft") || a.keys.has("a")) x -= 420 * dt; if (a.keys.has("ArrowRight") || a.keys.has("d")) x += 420 * dt; if (aim != null && !a.keys.has("ArrowLeft") && !a.keys.has("ArrowRight") && Math.abs(aim - x) > 8) x += Math.sign(aim - x) * Math.min(Math.abs(aim - x), 420 * dt); x = clamp(x, 28, AW - 28); if ((next -= dt) <= 0) { next = Math.max(.18, .48 - T * .01); items.push({ x: rnd(26, AW - 26), y: -20, vy: 210 + T * 6, k: Math.random() < .52 ? "ice" : Math.random() < .78 ? "gift" : "star" }); } for (const o of items) { o.y += o.vy * dt; if (!o.hit && Math.abs(o.y - 368) < 24 && Math.abs(o.x - x) < 28) { o.hit = 1; if (o.k === "ice") { hits++; a.add(-3); a.blip(); if (hits >= 3) a.end(); } else { a.add(o.k === "star" ? 5 : 2); a.tone(o.k === "star" ? 880 : 620); } } } items = items.filter((o) => !o.hit && o.y < AH + 30); }, draw(g, t) { sky(g, "#102448", "#2d5284"); flakes(g, t); g.fillStyle = "#eef4fa"; g.fillRect(0, AH - 34, AW, 34); for (const o of items) { if (o.k === "ice") { g.fillStyle = "#bfe6f7"; g.beginPath(); g.moveTo(o.x - 10, o.y - 18); g.lineTo(o.x + 10, o.y - 18); g.lineTo(o.x, o.y + 18); g.fill(); } else if (o.k === "gift") gift(g, o.x, o.y, 13); else star(g, o.x, o.y, 14); } g.fillStyle = "#e8862e"; g.beginPath(); g.arc(x, 368, 17, 0, 7); g.fill(); g.fillStyle = "#e0343e"; g.fillRect(x - 14, 348, 28, 8); text(g, "♥".repeat(3 - hits), AW / 2, 28, "#ff6a7a", "900 20px system-ui"); } }; };

const bells = (a) => { const FR = [440, 523, 659, 784], KEYS = ["a", "s", "d", "f"]; let seq = [], step = 0, show = 0, T = 0, wait = 0, lit = -1, round = 1; const addNext = () => { seq.push(Math.floor(Math.random() * 4)); step = 0; show = 0; wait = T + .45; }; addNext(); const press = (i) => { if (show < seq.length) return; lit = i; a.tone(FR[i], .2); setTimeout(() => { if (lit === i) lit = -1; }, 160); if (seq[step] === i) { step++; a.add(2); if (step >= seq.length) { a.add(round * 3); round++; addNext(); } } else { a.blip(); a.add(-2); seq = []; round = 1; addNext(); } }; return { key: (k) => { const i = KEYS.indexOf(k); if (i >= 0) press(i); else if (ARROWS.includes(k)) press(ARROWS.indexOf(k)); }, down: (x) => press(clamp(Math.floor(x / (AW / 4)), 0, 3)), tick(dt) { T += dt; if (show < seq.length && T >= wait) { const i = seq[show]; lit = i; a.tone(FR[i], .2); setTimeout(() => { if (lit === i) lit = -1; }, 220); show++; wait = T + Math.max(.28, .48 - round * .02); } }, draw(g) { sky(g, "#181438", "#3a2460"); COLORS.forEach((c, i) => { const x = (i + .5) * AW / 4, on = lit === i; g.fillStyle = on ? "#fff4bf" : c; g.beginPath(); g.moveTo(x - 42, 270); g.quadraticCurveTo(x - 32, 160, x, 150); g.quadraticCurveTo(x + 32, 160, x + 42, 270); g.fill(); g.beginPath(); g.arc(x, 276, 11, 0, 7); g.fill(); text(g, KEYS[i].toUpperCase(), x, 326, "#fff", "900 22px system-ui"); }); text(g, show < seq.length ? "Watch the bells..." : `Your turn! (Round ${round})`, AW / 2, 54, "#ffd27a", "900 22px system-ui"); } }; };

const snowfort = (a) => { let imps = [], T = 0, next = 0, hp = 5, pops = []; const hitAt = (x, y) => { const i = imps.findIndex((m) => Math.hypot(m.x - x, m.y - y) < 30); if (i >= 0) { const m = imps.splice(i, 1)[0]; a.add(m.gold ? 4 : 2); a.tone(m.gold ? 880 : 620); pops.push({ x: m.x, y: m.y - 20, t: m.gold ? "+4" : "+2", life: .6 }); } }; return { down: hitAt, key: (k) => { if (k === " " && imps.length) hitAt(imps[0].x, imps[0].y); }, tick(dt) { T += dt; if ((next -= dt) <= 0) { next = Math.max(.26, .75 - T * .014); const g = Math.random() < .2; imps.push({ x: AW + 20, y: rnd(70, AH - 50), v: (g ? 140 : 90) + T * 3, gold: g }); } for (const m of imps) { m.x -= m.v * dt; if (m.x < 88) { m.gone = 1; hp--; a.blip(); if (hp <= 0) a.end(); } } imps = imps.filter((m) => !m.gone); for (const p of pops) p.life -= dt; pops = pops.filter((p) => p.life > 0); }, draw(g, t) { sky(g, "#16264a", "#3c5c94"); flakes(g, t); g.fillStyle = "#dfeaf6"; g.fillRect(0, 0, 84, AH); g.strokeStyle = "#b5cde0"; g.lineWidth = 3; for (let y = 20; y < AH; y += 36) g.strokeRect(4, y, 76, 32); for (const m of imps) { g.fillStyle = m.gold ? "#ffd84d" : "#c83a48"; g.beginPath(); g.arc(m.x, m.y, 18, 0, 7); g.fill(); g.fillStyle = "#fff"; g.fillRect(m.x - 7, m.y - 5, 4, 4); g.fillRect(m.x + 2, m.y - 5, 4, 4); } for (const p of pops) text(g, p.t, p.x, p.y, "#ffd27a", "900 18px system-ui"); text(g, "Wall: " + "♥".repeat(Math.max(0, hp)), AW / 2, 28, "#ff6a7a", "900 20px system-ui"); } }; };

const cocoa = (a) => { let mugs = Array.from({ length: 4 }, (_, i) => ({ x: 135 + i * 150, need: 0, fill: 0, wait: 0 })); let T = 0, next = .3, miss = 0; const pour = (i) => { const m = mugs[i]; if (!m || !m.need) return; m.fill = Math.min(1, m.fill + .35); a.tone(500 + m.fill * 260, .08); if (m.fill >= 1) { a.add(4); a.tone(880); m.need = 0; m.fill = 0; } }; return { key: (k) => { const i = ["1", "2", "3", "4"].indexOf(k); if (i >= 0) pour(i); else if (ARROWS.includes(k)) pour(ARROWS.indexOf(k)); }, down: (x) => pour(clamp(Math.floor((x - 60) / 150), 0, 3)), tick(dt) { T += dt; if ((next -= dt) <= 0) { next = Math.max(.45, 1.1 - T * .012); const free = mugs.filter((m) => !m.need); if (free.length) { const m = pick(free); m.need = 1; m.fill = 0; m.wait = T + Math.max(2.0, 3.8 - T * .03); } } for (const m of mugs) if (m.need && T > m.wait) { m.need = 0; m.fill = 0; miss++; a.blip(); if (miss >= 5) a.end(); } }, draw(g) { g.fillStyle = "#3a2218"; g.fillRect(0, 0, AW, AH); g.fillStyle = "#6a4528"; g.fillRect(0, 290, AW, 130); mugs.forEach((m, i) => { g.fillStyle = m.need ? "#eef4fa" : "rgba(255,255,255,.15)"; g.fillRect(m.x - 32, 210, 64, 78); if (m.need) { g.fillStyle = "#6a3f25"; g.fillRect(m.x - 26, 282 - m.fill * 64, 52, m.fill * 64); text(g, `${Math.max(0, m.wait - T).toFixed(1)}s`, m.x, 194, "#ffd27a"); } text(g, i + 1, m.x, 340, "#fff", "900 22px system-ui"); }); text(g, `Missed ${miss}/5`, AW / 2, 34, "#ffd27a"); } }; };

const snowplow = (a) => { let x = 360, y = 210, drifts = [], rocks = [], bells = [], T = 0, hits = 0, aim = null; const spawn = () => { for (let i = 0; i < 6; i++) drifts.push({ x: rnd(50, AW - 50), y: rnd(60, AH - 40) }); for (let i = 0; i < 3; i++) bells.push({ x: rnd(50, AW - 50), y: rnd(60, AH - 40) }); for (let i = 0; i < 4; i++) rocks.push({ x: rnd(50, AW - 50), y: rnd(60, AH - 40) }); }; spawn(); return { move: (p, q) => (aim = [p, q]), tick(dt) { T += dt; let dx = 0, dy = 0; if (a.keys.has("ArrowLeft") || a.keys.has("a")) dx--; if (a.keys.has("ArrowRight") || a.keys.has("d")) dx++; if (a.keys.has("ArrowUp") || a.keys.has("w")) dy--; if (a.keys.has("ArrowDown") || a.keys.has("s")) dy++; if (!dx && !dy && aim) { const d = Math.hypot(aim[0] - x, aim[1] - y); if (d > 10) { dx = (aim[0] - x) / d; dy = (aim[1] - y) / d; } } const L = Math.hypot(dx, dy) || 1; x = clamp(x + dx / L * 260 * dt, 24, AW - 24); y = clamp(y + dy / L * 260 * dt, 48, AH - 24); for (const d of drifts) if (!d.got && Math.hypot(d.x - x, d.y - y) < 28) { d.got = 1; a.add(1); a.tone(540); } for (const b of bells) if (!b.got && Math.hypot(b.x - x, b.y - y) < 28) { b.got = 1; a.add(4); a.tone(860); } for (const r of rocks) if (!r.hit && Math.hypot(r.x - x, r.y - y) < 24) { r.hit = 1; hits++; a.add(-3); a.blip(); if (hits >= 3) a.end(); } drifts = drifts.filter((d) => !d.got); bells = bells.filter((b) => !b.got); rocks = rocks.filter((r) => !r.hit); if (!drifts.length && !bells.length) { a.add(6); spawn(); } }, draw(g) { g.fillStyle = "#cfe4f2"; g.fillRect(0, 0, AW, AH); for (const d of drifts) { g.fillStyle = "#fff"; g.beginPath(); g.ellipse(d.x, d.y, 20, 12, 0, 0, 7); g.fill(); } for (const b of bells) star(g, b.x, b.y, 13); for (const r of rocks) { g.fillStyle = "#5a606a"; g.beginPath(); g.arc(r.x, r.y, 14, 0, 7); g.fill(); } g.fillStyle = "#e0343e"; g.fillRect(x - 16, y - 14, 32, 28); g.fillStyle = "#ffd84d"; g.fillRect(x - 18, y - 18, 36, 7); text(g, "♥".repeat(3 - hits), AW / 2, 28, "#e0345e", "900 20px system-ui"); } }; };

const ornament = (a) => { let bx = 360, dir = 1, T = 0, shots = [], placed = []; const shoot = () => { if (shots.length < 3) { shots.push({ x: 360, y: 390, vy: -520 }); a.blip(); } }; return { down: shoot, key: (k) => k === " " && shoot(), tick(dt) { T += dt; bx += dir * (160 + T * 4) * dt; if (bx < 220 || bx > 500) { dir *= -1; bx = clamp(bx, 220, 500); } for (const s of shots) { s.y += s.vy * dt; if (s.y <= 210 && !s.done) { s.done = 1; if (Math.abs(s.x - bx) < 42) { placed.push({ dx: s.x - bx, c: pick(COLORS) }); a.add(3); a.tone(780); } else { a.add(-1); a.blip(); } } } shots = shots.filter((s) => !s.done && s.y > 0); }, draw(g, t) { sky(g, "#102040", "#264878"); flakes(g, t); pine(g, bx, 180, 4.2); for (const p of placed) { g.fillStyle = p.c; g.beginPath(); g.arc(bx + p.dx, 200, 9, 0, 7); g.fill(); } for (const s of shots) { g.fillStyle = "#ffd84d"; g.beginPath(); g.arc(s.x, s.y, 10, 0, 7); g.fill(); } text(g, "Click or Space to toss onto the swaying tree!", AW / 2, 34, "#ffd27a"); } }; };

const lanterns = (a) => { let list = [], T = 0, next = 0, miss = 0; const hit = (x, y) => { const i = list.findIndex((l) => !l.lit && Math.hypot(l.x - x, l.y - y) < 34); if (i >= 0) { list[i].lit = 1; a.add(list[i].gold ? 5 : 2); a.tone(list[i].gold ? 880 : 660); } }; return { down: hit, key: (k) => { if (k === " ") { const l = list.find((q) => !q.lit); if (l) hit(l.x, l.y); } }, tick(dt) { T += dt; if ((next -= dt) <= 0) { next = Math.max(.26, .68 - T * .012); list.push({ x: rnd(50, AW - 50), y: AH + 20, vy: 85 + T * 2.5, gold: Math.random() < .18, lit: 0 }); } for (const l of list) { l.y -= l.vy * dt; if (l.y < -30) { if (!l.lit) { miss++; a.blip(); if (miss >= 6) a.end(); } l.gone = 1; } } list = list.filter((l) => !l.gone); }, draw(g, t) { sky(g, "#0b1028", "#202e5a"); flakes(g, t); for (const l of list) { g.fillStyle = l.lit ? (l.gold ? "#ffd84d" : "#ff9a3a") : "#4a526e"; g.beginPath(); g.roundRect(l.x - 16, l.y - 22, 32, 42, 8); g.fill(); if (l.lit) { g.fillStyle = "#fff4bf"; g.beginPath(); g.arc(l.x, l.y + 4, 7, 0, 7); g.fill(); } } text(g, `Missed ${miss}/6`, AW / 2, 32, "#ffd27a"); } }; };

const icicleclimb = (a) => { let x = 360, y = 320, vy = -380, cam = 0, ledges = Array.from({ length: 12 }, (_, i) => ({ x: rnd(70, AW - 70), y: 380 - i * 54, gold: i % 3 === 0 })); let aim = null; return { move: (p) => (aim = p), tick(dt) { if (a.keys.has("ArrowLeft") || a.keys.has("a")) x -= 340 * dt; if (a.keys.has("ArrowRight") || a.keys.has("d")) x += 340 * dt; if (aim != null && !a.keys.has("ArrowLeft") && !a.keys.has("ArrowRight") && Math.abs(aim - x) > 8) x += Math.sign(aim - x) * Math.min(Math.abs(aim - x), 340 * dt); x = clamp(x, 20, AW - 20); vy += 760 * dt; y += vy * dt; if (vy > 0) for (const l of ledges) if (Math.abs(x - l.x) < 46 && Math.abs(y - l.y) < 14) { vy = -430; a.tone(l.gold ? 820 : 560); a.add(l.gold ? 3 : 1); } cam = Math.min(cam, y - 190); if (y - cam > AH + 30) { a.blip(); a.end(); } while (ledges[ledges.length - 1].y > cam - 60) { const top = ledges[ledges.length - 1]; ledges.push({ x: rnd(70, AW - 70), y: top.y - 54, gold: Math.random() < .35 }); } ledges = ledges.filter((l) => l.y - cam < AH + 40); }, draw(g, t) { sky(g, "#102850", "#3a6ca0"); flakes(g, t); for (const l of ledges) { g.fillStyle = l.gold ? "#ffd84d" : "#bfe6f7"; g.beginPath(); g.roundRect(l.x - 40, l.y - cam - 6, 80, 12, 6); g.fill(); } g.fillStyle = "#e8862e"; g.beginPath(); g.arc(x, y - cam - 12, 14, 0, 7); g.fill(); } }; };

const giftdrop = (a) => { let x = 360, T = 0, next = 0, drops = [], hits = 0, aim = null; return { move: (p) => (aim = p), tick(dt) { T += dt; if (a.keys.has("ArrowLeft") || a.keys.has("a")) x -= 440 * dt; if (a.keys.has("ArrowRight") || a.keys.has("d")) x += 440 * dt; if (aim != null && !a.keys.has("ArrowLeft") && !a.keys.has("ArrowRight") && Math.abs(aim - x) > 8) x += Math.sign(aim - x) * Math.min(Math.abs(aim - x), 440 * dt); x = clamp(x, 36, AW - 36); if ((next -= dt) <= 0) { next = Math.max(.2, .52 - T * .01); const r = Math.random(); drops.push({ x: rnd(30, AW - 30), y: -20, vy: 200 + T * 5, k: r < .28 ? "coal" : r < .44 ? "star" : "gift" }); } for (const d of drops) { d.y += d.vy * dt; if (!d.got && Math.abs(d.y - 362) < 22 && Math.abs(d.x - x) < 36) { d.got = 1; if (d.k === "coal") { hits++; a.add(-3); a.blip(); if (hits >= 3) a.end(); } else { a.add(d.k === "star" ? 5 : 2); a.tone(d.k === "star" ? 880 : 640); } } } drops = drops.filter((d) => !d.got && d.y < AH + 30); }, draw(g, t) { sky(g, "#0e1c3c", "#2d4c84"); flakes(g, t); g.fillStyle = "#eef4fa"; g.fillRect(0, AH - 30, AW, 30); for (const d of drops) { if (d.k === "coal") { g.fillStyle = "#222"; g.beginPath(); g.arc(d.x, d.y, 13, 0, 7); g.fill(); } else if (d.k === "gift") gift(g, d.x, d.y, 13); else star(g, d.x, d.y, 14); } g.fillStyle = "#b5432a"; g.fillRect(x - 28, 352, 56, 20); g.fillStyle = "#ffd27a"; g.fillRect(x - 32, 372, 64, 4); text(g, "♥".repeat(3 - hits), AW / 2, 28, "#ff6a7a", "900 20px system-ui"); } }; };

const snowmaze = (a) => { let x = 360, y = 210, stars = Array.from({ length: 4 }, () => ({ x: rnd(50, AW - 50), y: rnd(60, AH - 40) })), wisps = Array.from({ length: 4 }, () => ({ x: rnd(80, AW - 80), y: rnd(70, AH - 50), vx: (Math.random() < .5 ? 1 : -1) * 140, vy: (Math.random() < .5 ? 1 : -1) * 110 })), hits = 0, inv = 0, T = 0, aim = null; return { move: (p, q) => (aim = [p, q]), tick(dt) { T += dt; inv -= dt; let dx = 0, dy = 0; if (a.keys.has("ArrowLeft") || a.keys.has("a")) dx--; if (a.keys.has("ArrowRight") || a.keys.has("d")) dx++; if (a.keys.has("ArrowUp") || a.keys.has("w")) dy--; if (a.keys.has("ArrowDown") || a.keys.has("s")) dy++; if (!dx && !dy && aim) { const d = Math.hypot(aim[0] - x, aim[1] - y); if (d > 10) { dx = (aim[0] - x) / d; dy = (aim[1] - y) / d; } } const L = Math.hypot(dx, dy) || 1; x = clamp(x + dx / L * 260 * dt, 20, AW - 20); y = clamp(y + dy / L * 260 * dt, 46, AH - 20); for (const s of stars) if (Math.hypot(s.x - x, s.y - y) < 26) { s.x = rnd(50, AW - 50); s.y = rnd(60, AH - 40); a.add(3); a.tone(760); } for (const w of wisps) { w.x += w.vx * dt; w.y += w.vy * dt; if (w.x < 24 || w.x > AW - 24) w.vx *= -1; if (w.y < 52 || w.y > AH - 24) w.vy *= -1; if (inv <= 0 && Math.hypot(w.x - x, w.y - y) < 26) { inv = 1.1; hits++; a.add(-2); a.blip(); if (hits >= 3) a.end(); } } }, draw(g) { sky(g, "#102a44", "#224d6c"); for (const s of stars) star(g, s.x, s.y, 13); for (const w of wisps) { g.fillStyle = "#7fe8ff"; g.beginPath(); g.arc(w.x, w.y, 14, 0, 7); g.fill(); } if (inv <= 0 || Math.floor(T * 12) % 2) { g.fillStyle = "#e8862e"; g.beginPath(); g.arc(x, y, 15, 0, 7); g.fill(); } text(g, "♥".repeat(3 - hits), AW / 2, 28, "#ff6a7a", "900 20px system-ui"); } }; };

const carolbell = (a) => { let chimes = [], T = 0, next = 0, miss = 0; const hit = (x, y) => { const i = chimes.findIndex((c) => Math.hypot(c.x - x, c.y - y) < c.r + 10); if (i >= 0) { const c = chimes.splice(i, 1)[0]; a.add(c.gold ? 5 : 2); a.tone(c.gold ? 880 : 660); } }; return { down: hit, key: (k) => { if (k === " " && chimes.length) hit(chimes[0].x, chimes[0].y); }, tick(dt) { T += dt; if ((next -= dt) <= 0) { next = Math.max(.26, .66 - T * .012); chimes.push({ x: rnd(60, AW - 60), y: rnd(70, AH - 50), r: 26, end: T + 1.5, gold: Math.random() < .2 }); } for (const c of chimes) if (T > c.end) { c.gone = 1; miss++; a.blip(); if (miss >= 6) a.end(); } chimes = chimes.filter((c) => !c.gone); }, draw(g, t) { sky(g, "#161238", "#34245e"); flakes(g, t); for (const c of chimes) { g.fillStyle = c.gold ? "#ffd84d" : "#b58cff"; g.beginPath(); g.arc(c.x, c.y, c.r, 0, 7); g.fill(); star(g, c.x, c.y, c.r * .6, "#fff"); } text(g, `Missed ${miss}/6`, AW / 2, 32, "#ffd27a"); } }; };
const sleighrace = (a) => { let lane = 1, objs = [], T = 0, next = 0, lives = 3; const ys = [130, 225, 320]; return { move: (_, y) => { lane = clamp(Math.floor((y - 80) / 95), 0, 2); }, key: (k) => { if (k === "ArrowUp" || k === "w") lane = Math.max(0, lane - 1); if (k === "ArrowDown" || k === "s") lane = Math.min(2, lane + 1); }, tick(dt) { T += dt; if ((next -= dt) <= 0) { next = Math.max(.28, .68 - T * .01); objs.push({ lane: Math.floor(rnd(0, 3)), x: AW + 30, bad: Math.random() < .42, gold: Math.random() < .2 }); } const sp = 280 + T * 5; for (const o of objs) { o.x -= sp * dt; if (o.lane === lane && Math.abs(o.x - 110) < 34) { o.hit = 1; if (o.bad) { lives--; a.blip(); if (lives <= 0) a.end(); } else { a.add(o.gold ? 4 : 2); a.tone(o.gold ? 880 : 620); } } } objs = objs.filter((o) => !o.hit && o.x > -40); }, draw(g, t) { sky(g, "#10183a", "#263a72"); flakes(g, t); g.strokeStyle = "rgba(255,255,255,.18)"; g.lineWidth = 2; for (const y of ys) { g.beginPath(); g.moveTo(0, y + 32); g.lineTo(AW, y + 32); g.stroke(); } for (const o of objs) { const y = ys[o.lane]; if (o.bad) pine(g, o.x, y + 18, 1); else if (o.gold) star(g, o.x, y, 16, "#ffd84d"); else gift(g, o.x - 13, y - 13, 26, "#ff7282"); } g.fillStyle = "#e0343e"; g.fillRect(82, ys[lane] - 12, 56, 24); g.fillStyle = "#ffd84d"; g.fillRect(80, ys[lane] + 12, 60, 6); text(g, `Lives ${lives}`, AW / 2, 32, "#ffd27a"); } }; };
const snowglobe = (a) => { let orbs = [], T = 0, next = 0, miss = 0; const hit = (x, y) => { const i = orbs.findIndex((o) => Math.hypot(o.x - x, o.y - y) < o.r + 12); if (i >= 0) { const o = orbs.splice(i, 1)[0]; a.add(o.gold ? 5 : 2); a.tone(o.gold ? 920 : 700); } }; return { down: hit, key: (k) => { if (k === " " && orbs.length) hit(orbs[0].x, orbs[0].y); }, tick(dt) { T += dt; if ((next -= dt) <= 0) { next = Math.max(.3, .72 - T * .01); orbs.push({ x: rnd(70, AW - 70), y: rnd(80, AH - 70), r: 28, end: T + 1.65, gold: Math.random() < .24 }); } for (const o of orbs) if (T > o.end) { o.gone = 1; miss++; a.blip(); if (miss >= 6) a.end(); } orbs = orbs.filter((o) => !o.gone); }, draw(g, t) { sky(g, "#0f223d", "#244d75"); flakes(g, t); for (const o of orbs) { g.fillStyle = "rgba(180,235,255,.28)"; g.beginPath(); g.arc(o.x, o.y, o.r, 0, 7); g.fill(); g.strokeStyle = o.gold ? "#ffd84d" : "#7fe8ff"; g.lineWidth = 3; g.stroke(); star(g, o.x, o.y, o.r * .5, o.gold ? "#ffd84d" : "#fff"); } text(g, `Settled ${miss}/6`, AW / 2, 32, "#7fe8ff"); } }; };
const presentpile = (a) => { let px = AW / 2, vx = 240, bx = AW / 2, bw = 120, stack = [], h = 0; const drop = () => { const diff = Math.abs(px - bx); if (diff > bw * .72) { a.blip(); return a.end(); } bw = Math.max(36, bw - diff * .55); bx = (bx + px) / 2; h++; stack.push({ x: bx, w: bw, c: pick(COLORS) }); a.add(diff < 12 ? 5 : 2); a.tone(520 + h * 25); vx = (vx > 0 ? 1 : -1) * Math.min(460, Math.abs(vx) + 12); }; return { down: drop, key: (k) => { if (k === " ") drop(); }, tick(dt) { px += vx * dt; if (px < 80 || px > AW - 80) vx *= -1; }, draw(g, t) { sky(g, "#1d1438", "#3b235a"); flakes(g, t); g.fillStyle = "#c98f4e"; g.fillRect(AW / 2 - 90, AH - 34, 180, 20); stack.slice(-8).forEach((s, i) => { g.fillStyle = s.c; g.fillRect(s.x - s.w / 2, AH - 58 - i * 24, s.w, 22); }); g.fillStyle = "#ff7282"; g.fillRect(px - bw / 2, 64, bw, 22); text(g, `Stacked ${h}`, AW / 2, 32, "#ffd84d"); } }; };
const icehockey = (a) => { let px = AW / 2, puck = { x: AW / 2, y: 120, vx: 190, vy: 220 }, miss = 0; return { move: (x) => { px = clamp(x, 70, AW - 70); }, tick(dt) { if (a.keys.has("ArrowLeft") || a.keys.has("a")) px = Math.max(70, px - 460 * dt); if (a.keys.has("ArrowRight") || a.keys.has("d")) px = Math.min(AW - 70, px + 460 * dt); puck.x += puck.vx * dt; puck.y += puck.vy * dt; if (puck.x < 24 || puck.x > AW - 24) puck.vx *= -1; if (puck.y < 36) { puck.vy = Math.abs(puck.vy); if (Math.abs(puck.x - AW / 2) < 95) { a.add(4); a.tone(840); } } if (puck.y > AH - 42 && puck.y < AH - 20 && Math.abs(puck.x - px) < 62 && puck.vy > 0) { puck.vy = -Math.min(460, Math.abs(puck.vy) * 1.04 + 8); puck.vx += (puck.x - px) * 2.5; a.add(1); a.tone(540); } if (puck.y > AH + 12) { miss++; a.blip(); if (miss >= 4) a.end(); puck = { x: AW / 2, y: 120, vx: (Math.random() < .5 ? -1 : 1) * 190, vy: 220 }; } }, draw(g, t) { sky(g, "#16304c", "#2c5b84"); flakes(g, t); g.fillStyle = "#ffd84d"; g.fillRect(AW / 2 - 95, 16, 190, 12); g.fillStyle = "#5ef2b6"; g.fillRect(px - 56, AH - 34, 112, 14); g.fillStyle = "#182030"; g.beginPath(); g.arc(puck.x, puck.y, 12, 0, 7); g.fill(); text(g, `Missed ${miss}/4`, AW / 2, 54, "#ffd27a"); } }; };
const icecastles = (a) => { let foe = [], T = 0, next = 0, hp = 5; const hit = (x, y) => { const i = foe.findIndex((f) => Math.hypot(f.x - x, f.y - y) < 28); if (i >= 0) { const f = foe.splice(i, 1)[0]; a.add(f.gold ? 5 : 2); a.tone(f.gold ? 880 : 620); } }; return { down: hit, key: (k) => { if (k === " " && foe.length) hit(foe[0].x, foe[0].y); }, tick(dt) { T += dt; if ((next -= dt) <= 0) { next = Math.max(.26, .68 - T * .01); foe.push({ x: AW + 20, y: rnd(75, AH - 65), vx: rnd(130, 210) + T * 2, gold: Math.random() < .2 }); } for (const f of foe) { f.x -= f.vx * dt; if (f.x < 68) { f.gone = 1; hp--; a.blip(); if (hp <= 0) a.end(); } } foe = foe.filter((f) => !f.gone); }, draw(g, t) { sky(g, "#10203a", "#264878"); flakes(g, t); g.fillStyle = "#9fe8ff"; g.fillRect(28, 48, 34, AH - 80); for (const f of foe) { g.fillStyle = f.gold ? "#ffd84d" : "#ff6b6b"; g.beginPath(); g.arc(f.x, f.y, 18, 0, 7); g.fill(); } text(g, `Wall ${hp}/5`, AW / 2, 32, "#7fe8ff"); } }; };
const starfetch = (a) => { let px = AW / 2, drops = [], T = 0, next = 0, lives = 3; return { move: (x) => { px = clamp(x, 40, AW - 40); }, tick(dt) { T += dt; if (a.keys.has("ArrowLeft") || a.keys.has("a")) px = Math.max(40, px - 460 * dt); if (a.keys.has("ArrowRight") || a.keys.has("d")) px = Math.min(AW - 40, px + 460 * dt); if ((next -= dt) <= 0) { next = Math.max(.24, .58 - T * .008); drops.push({ x: rnd(40, AW - 40), y: -20, vy: rnd(170, 260) + T * 3, bad: Math.random() < .26, gold: Math.random() < .25 }); } for (const d of drops) { d.y += d.vy * dt; if (Math.abs(d.x - px) < 36 && d.y > AH - 68 && d.y < AH - 26) { d.hit = 1; if (d.bad) { lives--; a.blip(); if (lives <= 0) a.end(); } else { a.add(d.gold ? 5 : 2); a.tone(d.gold ? 900 : 660); } } } drops = drops.filter((d) => !d.hit && d.y < AH + 25); }, draw(g, t) { sky(g, "#0b1026", "#1d2b58"); flakes(g, t); for (const d of drops) { if (d.bad) { g.fillStyle = "#3a4052"; g.beginPath(); g.arc(d.x, d.y, 14, 0, 7); g.fill(); } else star(g, d.x, d.y, d.gold ? 18 : 13, d.gold ? "#ffd84d" : "#b58cff"); } g.fillStyle = "#ffd84d"; g.fillRect(px - 34, AH - 48, 68, 18); text(g, `Lives ${lives}`, AW / 2, 32, "#ffd27a"); } }; };
const bellsprint = (a) => { let seq = [], T = 0, next = 0, miss = 0; const lanes = [180, 300, 420, 540], cols = ["#e0343e", "#ffd84d", "#5cf0c0", "#7fe8ff"], ks = ["a", "s", "d", "f"]; const hit = (i) => { const idx = seq.findIndex((b) => b.lane === i && Math.abs(b.y - (AH - 68)) < 46); if (idx >= 0) { seq.splice(idx, 1); a.add(3); a.tone(520 + i * 110); } else { a.blip(); } }; return { down: (x) => { const i = lanes.findIndex((lx) => Math.abs(lx - x) < 55); if (i >= 0) hit(i); }, key: (k) => { const i = ks.indexOf(k); if (i >= 0) hit(i); }, tick(dt) { T += dt; if ((next -= dt) <= 0) { next = Math.max(.28, .66 - T * .009); seq.push({ lane: Math.floor(rnd(0, 4)), y: -20, vy: 210 + T * 3 }); } for (const b of seq) { b.y += b.vy * dt; if (b.y > AH + 10) { b.gone = 1; miss++; a.blip(); if (miss >= 6) a.end(); } } seq = seq.filter((b) => !b.gone); }, draw(g, t) { sky(g, "#180d2c", "#321b54"); flakes(g, t); lanes.forEach((lx, i) => { g.strokeStyle = cols[i]; g.lineWidth = 3; g.beginPath(); g.arc(lx, AH - 68, 26, 0, 7); g.stroke(); }); for (const b of seq) { g.fillStyle = cols[b.lane]; g.beginPath(); g.arc(lanes[b.lane], b.y, 18, 0, 7); g.fill(); } text(g, `Missed ${miss}/6`, AW / 2, 32, "#ffd84d"); } }; };
const frostslide = (a) => { let y = AH / 2, obs = [], T = 0, next = 0, lives = 3; return { move: (_, my) => { y = clamp(my, 50, AH - 50); }, tick(dt) { T += dt; if (a.keys.has("ArrowUp") || a.keys.has("w")) y = Math.max(50, y - 340 * dt); if (a.keys.has("ArrowDown") || a.keys.has("s")) y = Math.min(AH - 50, y + 340 * dt); if ((next -= dt) <= 0) { next = Math.max(.26, .62 - T * .009); obs.push({ x: AW + 25, y: rnd(60, AH - 60), bad: Math.random() < .4, gold: Math.random() < .2 }); } const sp = 250 + T * 4; for (const o of obs) { o.x -= sp * dt; if (Math.hypot(o.x - 105, o.y - y) < 32) { o.hit = 1; if (o.bad) { lives--; a.blip(); if (lives <= 0) a.end(); } else { a.add(o.gold ? 5 : 2); a.tone(o.gold ? 880 : 620); } } } obs = obs.filter((o) => !o.hit && o.x > -30); }, draw(g, t) { sky(g, "#0b2438", "#1d4f72"); flakes(g, t); for (const o of obs) { if (o.bad) pine(g, o.x, o.y + 14, .9); else star(g, o.x, o.y, o.gold ? 18 : 13, o.gold ? "#ffd84d" : "#5cf0c0"); } g.fillStyle = "#ff9a3a"; g.beginPath(); g.arc(105, y, 18, 0, 7); g.fill(); text(g, `Lives ${lives}`, AW / 2, 32, "#ffd27a"); } }; };

const iciclebridge = (a) => { let pos = 0, cam = 0, T = 0, hits = 0, planks = [{ off: 1, sp: 0, gold: false }, { off: 2, sp: 1.2, gold: false }]; const step = () => { const p = planks[pos + 1]; if (!p) return; if (Math.sin(T * p.sp + p.off) > 0) { pos++; a.add(p.gold ? 5 : 2); a.tone(p.gold ? 880 : 620); planks.push({ off: Math.random() * 6.28, sp: Math.min(4, 1.2 + planks.length * .07), gold: Math.random() < .2 }); } else { hits++; a.add(-3); a.blip(); if (hits >= 3) a.end(); } }; return { key: (k) => { if (k === " " || k === "ArrowUp" || k === "ArrowRight" || k === "w" || k === "d") step(); }, down: () => step(), tick(dt) { T += dt; cam += (pos - cam) * Math.min(1, dt * 5); }, draw(g, t) { sky(g, "#0e2040", "#2d5284"); flakes(g, t); g.fillStyle = "#091430"; g.fillRect(0, 300, AW, AH - 300); g.strokeStyle = "#8a5a32"; g.lineWidth = 3; g.beginPath(); g.moveTo(0, 252); g.lineTo(AW, 242); g.stroke(); g.beginPath(); g.moveTo(0, 280); g.lineTo(AW, 270); g.stroke(); planks.forEach((p, i) => { const x = 150 + (i - cam) * 78; if (x < -70 || x > AW + 70) return; const safe = Math.sin(T * p.sp + p.off) > 0; g.fillStyle = safe ? (p.gold ? "#ffd84d" : "#dff1ff") : "#31517c"; g.beginPath(); g.roundRect(x - 34, 258, 68, 16, 5); g.fill(); if (!safe) { g.strokeStyle = "#0d1c33"; g.lineWidth = 2; g.beginPath(); g.moveTo(x - 18, 262); g.lineTo(x - 6, 268); g.lineTo(x + 4, 261); g.lineTo(x + 16, 269); g.stroke(); } else if (p.gold) star(g, x, 246, 9); }); const px = 150 + (pos - cam) * 78; g.fillStyle = "#e8862e"; g.beginPath(); g.arc(px, 240, 15, 0, 7); g.fill(); g.fillStyle = "#23233a"; g.fillRect(px - 8, 235, 4, 4); g.fillRect(px + 4, 235, 4, 4); g.fillStyle = "#d3312f"; g.fillRect(px - 15, 250, 30, 7); text(g, "Step while the ice is pale — dark planks creak!", AW / 2, 330, "#ffd27a"); text(g, "♥".repeat(3 - hits), AW / 2, 28, "#ff6a7a", "900 20px system-ui"); } }; };

const wassail = (a) => { let guests = [], T = 0, next = .3, miss = 0; const serve = (i) => { const g = guests.filter((q) => q.c === i).sort((p, q) => p.wait - q.wait)[0]; if (!g) return a.blip(); guests.splice(guests.indexOf(g), 1); a.add(g.gold ? 5 : 2); a.tone(g.gold ? 880 : 660); }; return { key: (k) => { let i = ARROWS.indexOf(k); if (i < 0) i = ["a", "s", "d", "f"].indexOf(k); if (i >= 0) serve(i); }, down: (x) => serve(clamp(Math.floor(x / (AW / 4)), 0, 3)), tick(dt) { T += dt; if ((next -= dt) <= 0 && guests.length < 6) { next = Math.max(.5, 1.15 - T * .012); const d = Math.max(1.7, 3.4 - T * .022); guests.push({ c: Math.floor(Math.random() * 4), wait: T + d, dur: d, gold: Math.random() < .18 }); } for (const g of guests) if (T > g.wait) { g.gone = 1; miss++; a.blip(); if (miss >= 5) a.end(); } guests = guests.filter((g) => !g.gone); }, draw(g, t) { sky(g, "#1a1030", "#3a2452"); flakes(g, t); g.fillStyle = "#6a4528"; g.fillRect(0, 250, AW, 44); g.fillStyle = "#3a2a22"; g.fillRect(0, 294, AW, AH - 294); COLORS.forEach((c, i) => { const x = (i + .5) * AW / 4; g.fillStyle = c; g.beginPath(); g.roundRect(x - 62, 310, 124, 80, 12); g.fill(); text(g, ARROW_T[i], x, 362, "#fff", "900 34px system-ui"); }); guests.forEach((q, i) => { const x = 96 + i * 106; g.fillStyle = "#ffd27a"; g.fillRect(x - 16, 156, 32 * Math.max(0, (q.wait - T) / q.dur), 4); g.fillStyle = COLORS[q.c]; g.beginPath(); g.arc(x, 182, 11, 0, 7); g.fill(); text(g, ARROW_T[q.c], x, 188, "#fff", "800 13px system-ui"); g.fillStyle = q.gold ? "#ffd84d" : "#eef4fa"; g.beginPath(); g.arc(x, 208, 11, 0, 7); g.arc(x, 232, 16, 0, 7); g.fill(); g.fillStyle = "#23233a"; g.fillRect(x - 6, 205, 3, 3); g.fillRect(x + 3, 205, 3, 3); g.fillStyle = "#e8862e"; g.fillRect(x - 1, 209, 8, 3); }); text(g, `Missed ${miss}/5`, AW / 2, 34, "#ffd27a"); } }; };

